// D10 · Part 0~5 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d10_flow.ts
//   Part 1 편집 거리 · WER/CER → Part 2 정규화 → Part 3 회의록 파이프라인 → Part 4 요약 → Part 5 평가표
//   OPENAI_API_KEY 있으면 Whisper API 받아쓰기, ANTHROPIC_API_KEY 있으면 Claude 요약 (없으면 건너뜀 · 규칙 기반)
//   데모 화면은 d10_demo.ts --serve 로 따로 열어요.
//   실제 회의 녹음으로 해 보려면: node --experimental-strip-types d10_flow.ts 회의.wav (없으면 합성 신호 · 흐름 확인용)
import { existsSync, readFileSync, writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
const SR = 16000; // 음성 모델 입력 표준: 16kHz mono

function mulberry32(seed: number): () => number {
  // 씨앗(seed)이 같으면 늘 같은 난수 순서 (0 이상 1 미만)
  let a = seed >>> 0;
  return (): number => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function synthVoice(seconds: number = 2, f0: number = 140, seed: number = 0): Float32Array {
  // 말소리 비슷한 합성 신호(16kHz mono): 기본음 + 배음 5개 + 음절 모양 세기 + 약한 잡음
  const n = Math.floor(seconds * SR);
  const y = new Float32Array(n);
  const rnd = mulberry32(seed);
  let phase = 0;
  let peak = 1e-9;
  for (let i = 0; i < n; i++) {
    const t = i / SR;
    phase += (2 * Math.PI * f0 * (1 + 0.05 * Math.sin(2 * Math.PI * 0.7 * t))) / SR; // 억양처럼 천천히 오르내림
    let v = 0;
    for (let k = 1; k <= 5; k++) v += Math.sin(k * phase) / k;
    const env = Math.sqrt(Math.max(0, Math.sin(2 * Math.PI * 2.5 * t))); // 1초에 음절 5개쯤
    y[i] = v * env + 0.01 * (rnd() * 2 - 1);
    peak = Math.max(peak, Math.abs(y[i]));
  }
  for (let i = 0; i < n; i++) y[i] = (0.8 * y[i]) / peak;
  return y;
}

function writeWav(path: string, y: Float32Array, sr: number = SR): void {
  // 16-bit PCM mono WAV: 44바이트 머리말 + 샘플
  const buf = Buffer.alloc(44 + y.length * 2);
  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + y.length * 2, 4);
  buf.write("WAVEfmt ", 8, "ascii");
  buf.writeUInt32LE(16, 16); // fmt 덩어리 크기
  buf.writeUInt16LE(1, 20); // 1 = PCM
  buf.writeUInt16LE(1, 22); // 채널 1개 (mono)
  buf.writeUInt32LE(sr, 24);
  buf.writeUInt32LE(sr * 2, 28); // 1초 바이트 수
  buf.writeUInt16LE(2, 32); // 샘플 하나 바이트 수
  buf.writeUInt16LE(16, 34); // 16비트
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(y.length * 2, 40);
  for (let i = 0; i < y.length; i++) {
    const v = Math.max(-1, Math.min(1, y[i])); // -1~1 밖은 잘라 냄
    buf.writeInt16LE(Math.round(v * 32767), 44 + i * 2);
  }
  writeFileSync(path, buf);
}

function readWav(path: string): { y: Float32Array; sr: number; channels: number } {
  // PCM 16비트 · float 32비트 WAV를 읽어 mono Float32Array로 (여러 채널이면 평균)
  const b = readFileSync(path);
  if (b.length < 12 || b.toString("ascii", 0, 4) !== "RIFF" || b.toString("ascii", 8, 12) !== "WAVE") throw new Error(`${path}: WAV 파일이 아니에요`);
  let fmt = 0;
  let channels = 1;
  let sr = 0;
  let bits = 0;
  let pos = 12;
  while (pos + 8 <= b.length) {
    const id = b.toString("ascii", pos, pos + 4);
    const size = b.readUInt32LE(pos + 4);
    const body = pos + 8;
    if (id === "fmt ") {
      fmt = b.readUInt16LE(body);
      channels = b.readUInt16LE(body + 2);
      sr = b.readUInt32LE(body + 4);
      bits = b.readUInt16LE(body + 14);
    } else if (id === "data") {
      const end = Math.min(b.length, body + size); // 크기가 잘못 적힌 파일도 있는 만큼만 읽음
      const step = (bits / 8) * channels;
      if (!((fmt === 1 && bits === 16) || (fmt === 3 && bits === 32))) throw new Error(`${path}: 16비트 PCM 또는 32비트 float만 읽어요`);
      const n = Math.floor((end - body) / step);
      const y = new Float32Array(n);
      for (let i = 0; i < n; i++) {
        let s = 0;
        for (let c = 0; c < channels; c++) {
          const at = body + i * step + c * (bits / 8);
          s += fmt === 1 ? b.readInt16LE(at) / 32768 : b.readFloatLE(at);
        }
        y[i] = s / channels;
      }
      return { y, sr, channels };
    }
    pos = body + size + (size % 2); // 덩어리는 짝수 바이트로 맞춰 있음
  }
  throw new Error(`${path}: data 덩어리가 없어요`);
}
const N_FFT = 512; // Python은 400, 이 FFT는 2의 거듭제곱이 필요해서 512 (창 길이는 400 = 25ms)
const WIN = 400;
const HOP = 160; // 10ms
const N_MELS = 80;

function fft(re: Float64Array, im: Float64Array): void {
  // 제자리 FFT (쿨리-튜키)
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const a = i + k;
        const b = a + len / 2;
        const xr = re[b] * wr - im[b] * wi;
        const xi = re[b] * wi + im[b] * wr;
        re[b] = re[a] - xr;
        im[b] = im[a] - xi;
        re[a] += xr;
        im[a] += xi;
      }
    }
  }
}

const hz2mel = (f: number): number => 2595 * Math.log10(1 + f / 700);
const mel2hz = (m: number): number => 700 * (10 ** (m / 2595) - 1);

function melBank(sr: number): number[][] {
  // 삼각형 멜 필터 80개 (낮은 소리는 촘촘하게, 높은 소리는 성기게)
  const pts = Array.from({ length: N_MELS + 2 }, (_, i) => Math.floor(((N_FFT + 1) * mel2hz((hz2mel(sr / 2) * i) / (N_MELS + 1))) / sr));
  return Array.from({ length: N_MELS }, (_, m) => {
    const row = new Array<number>(N_FFT / 2 + 1).fill(0);
    for (let k = pts[m]; k < pts[m + 1]; k++) row[k] = (k - pts[m]) / Math.max(1, pts[m + 1] - pts[m]);
    for (let k = pts[m + 1]; k < pts[m + 2]; k++) row[k] = (pts[m + 2] - k) / Math.max(1, pts[m + 2] - pts[m + 1]);
    return row;
  });
}

function logMel(y: Float32Array, sr: number): number[][] {
  // 로그 멜 스펙트로그램 [시간 칸][멜 80] (dB, 가장 큰 값 = 0 dB)
  const bank = melBank(sr);
  const frames: number[][] = [];
  const re = new Float64Array(N_FFT);
  const im = new Float64Array(N_FFT);
  for (let s = 0; s + WIN <= y.length; s += HOP) {
    re.fill(0);
    im.fill(0);
    for (let i = 0; i < WIN; i++) re[i] = y[s + i] * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / WIN)); // 한(Hann) 창
    fft(re, im);
    const pow = Array.from({ length: N_FFT / 2 + 1 }, (_, k) => re[k] * re[k] + im[k] * im[k]);
    frames.push(bank.map((row) => row.reduce((acc, w, k) => acc + w * pow[k], 0)));
  }
  const top = frames.reduce((m, f) => Math.max(m, ...f), 1e-10); // 가장 큰 값
  return frames.map((f) => f.map((v) => 10 * Math.log10(Math.max(v, 1e-10) / top)));
}
function isRecord(v: unknown): v is Record<string, unknown> {
  // JSON 응답은 모양을 모르는 unknown → 객체인지 먼저 확인하고 꺼낸다
  return typeof v === "object" && v !== null && !Array.isArray(v);
}
type Word = { word: string; start: number; end: number; speaker?: string };
type SttResult = { text: string; words: Word[]; duration: number; elapsed: number; engine: string };

async function transcribe(path: string, language: string = "ko"): Promise<SttResult> {
  // 받아쓰기: OPENAI_API_KEY가 있으면 Whisper API(단어 시각 포함), 없으면 인식은 건너뛰고 파이프라인만 진행
  const { y, sr } = readWav(path);
  const duration = y.length / sr;
  const t0 = performance.now();
  const key = process.env.OPENAI_API_KEY;
  if (!key) return { text: "", words: [], duration, elapsed: 0, engine: "인식 생략 (OPENAI_API_KEY 없음)" };
  try {
    const form = new FormData();
    form.append("file", new Blob([new Uint8Array(readFileSync(path))], { type: "audio/wav" }), "audio.wav");
    form.append("model", "whisper-1");
    form.append("language", language);
    form.append("response_format", "verbose_json");
    form.append("timestamp_granularities[]", "word");
    const res = await fetch("https://api.openai.com/v1/audio/transcriptions", { method: "POST", headers: { Authorization: `Bearer ${key}` }, body: form });
    if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
    const data: unknown = await res.json();
    const text = isRecord(data) && typeof data.text === "string" ? data.text.trim() : "";
    const raw = isRecord(data) && Array.isArray(data.words) ? data.words : [];
    const words: Word[] = raw.filter(isRecord).map((w) => ({ word: String(w.word ?? ""), start: Number(w.start ?? 0), end: Number(w.end ?? 0) }));
    return { text, words, duration, elapsed: (performance.now() - t0) / 1000, engine: "OpenAI whisper-1" };
  } catch (e) {
    console.log(`[주의] STT 호출 실패 → 인식 생략: ${String(e).slice(0, 120)}`);
    return { text: "", words: [], duration, elapsed: (performance.now() - t0) / 1000, engine: "인식 실패" };
  }
}
function speechSegments(y: Float32Array, sr: number = SR, topDb: number = 30): Array<[number, number]> {
  // 말소리 구간(초): 25ms 창·10ms 간격의 세기가 가장 큰 창보다 topDb 이상 작으면 쉼으로 본다
  const win = Math.round(0.025 * sr);
  const hop = Math.round(0.01 * sr);
  const db: number[] = [];
  for (let s = 0; s + win <= y.length; s += hop) {
    let e = 0;
    for (let i = s; i < s + win; i++) e += y[i] * y[i];
    db.push(10 * Math.log10(e / win + 1e-12));
  }
  const top = db.length ? Math.max(...db) : 0;
  const segs: Array<[number, number]> = [];
  db.forEach((v, k) => {
    const t0 = (k * hop) / sr;
    const t1 = (k * hop + win) / sr;
    if (v < top - topDb) return;
    const last = segs[segs.length - 1];
    if (last && t0 - last[1] < 0.3) last[1] = t1; // 0.3초보다 짧은 쉼은 이어 붙임
    else segs.push([t0, t1]);
  });
  return segs.filter(([a, b]) => b - a > 0.3);
}
function resample(y: Float32Array, from: number, to: number = SR): Float32Array {
  // 선형 보간으로 샘플링 레이트 바꾸기 (예: 48000 → 16000)
  if (from === to) return y;
  const out = new Float32Array(Math.floor((y.length * to) / from));
  for (let i = 0; i < out.length; i++) {
    const x = (i * from) / to;
    const k = Math.floor(x);
    const a = y[k] ?? 0;
    const b = y[k + 1] ?? a;
    out[i] = a + (b - a) * (x - k);
  }
  return out;
}
function userWav(fallback: () => string, out: string = "input.wav"): string {
  // 입력 음성: 실행할 때 WAV 경로를 주면(예: node x.ts 내녹음.wav) 16kHz mono로 바꿔 쓰고, 없으면 합성 신호
  // 합성 신호는 말이 아니므로, API 키와 실제 음성이 없으면 이 코드는 '흐름 확인용'으로만 돈다
  const src = process.argv.slice(2).find((a) => !a.startsWith("--"));
  if (src && existsSync(src)) {
    const { y, sr } = readWav(src);
    writeWav(out, resample(y, sr), SR);
    console.log(`입력: ${src} → ${out} (16kHz mono)`);
    return out;
  }
  console.log("입력: 합성 신호 (실제 음성 WAV 경로를 주면 그 파일로) · 키 · 실제 음성이 없으면 흐름 확인용");
  return fallback();
}
async function callClaude(system: string, user: string, model: string, maxTokens: number): Promise<string> {
  // Anthropic Messages API를 fetch로 직접 호출 (키는 환경 변수에서만 읽는다)
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) throw new Error("ANTHROPIC_API_KEY 없음");
  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: { "x-api-key": key, "anthropic-version": "2023-06-01", "content-type": "application/json" },
    body: JSON.stringify({ model, max_tokens: maxTokens, system, messages: [{ role: "user", content: user }] }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}`); // 응답 본문은 로그에 남기지 않음
  const data: unknown = await res.json();
  const blocks = isRecord(data) && Array.isArray(data.content) ? data.content : [];
  return blocks.filter(isRecord).filter((b) => b.type === "text" && typeof b.text === "string").map((b) => String(b.text)).join("");
}
function editDistance<T>(r: T[], h: T[]): number[][] {
  // 편집 거리 표: d[i][j] = 정답 앞 i개를 결과 앞 j개로 바꾸는 최소 고침 횟수
  const n = r.length;
  const m = h.length;
  const d = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));
  for (let i = 0; i <= n; i++) d[i][0] = i; // 결과가 비었으면 정답을 모두 '빠짐'
  for (let j = 0; j <= m; j++) d[0][j] = j; // 정답이 비었으면 결과가 모두 '끼어듦'
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      const cost = r[i - 1] === h[j - 1] ? 0 : 1;
      d[i][j] = Math.min(
        d[i - 1][j] + 1, // 빠짐 (D)
        d[i][j - 1] + 1, // 끼어듦 (I)
        d[i - 1][j - 1] + cost, // 같음(0) 또는 바꿈 (S)
      );
    }
  }
  return d;
}

const corner = (d: number[][]): number => d[d.length - 1][d[0].length - 1]; // 오른쪽 아래 칸 = 최소 고침 횟수
function errorRate<T>(r: T[], h: T[]): number {
  // 오류율 = 최소 고침 횟수 ÷ 정답 길이 (정답이 비면 0으로 나누게 되므로 오류)
  if (r.length === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return corner(editDistance(r, h)) / r.length;
}

const myWer = (ref: string, hyp: string): number => errorRate(ref.split(" ").filter(Boolean), hyp.split(" ").filter(Boolean));
const myCer = (ref: string, hyp: string): number => errorRate([...ref], [...hyp]); // 공백도 한 글자로 셈
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
function wer(ref: string | string[], hyp: string | string[]): number {
  // 단어 오류율 (jiwer.wer와 같은 방식: 공백으로 단어를 나눔)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  const split = (s: string): string[] => s.trim().split(/\s+/).filter(Boolean);
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rw = split(r);
    edits += editCount(rw, split(H[i] ?? ""));
    total += rw.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
const DIG = "영일이삼사오육칠팔구";
const UNITS = ["", "십", "백", "천"];

function num2kor(n: number): string {
  // 0~9999를 한글 읽기로: 2026 → 이천이십육 (만 이상은 그대로 둔다)
  if (n === 0) return "영";
  if (n >= 10000) return String(n);
  let s = "";
  [...String(n)].reverse().forEach((ch, i) => { // i = 0(일의 자리), 1(십), 2(백), 3(천)
    const d = Number(ch);
    if (d === 0) return;
    s = (d === 1 && i > 0 ? "" : DIG[d]) + UNITS[i] + s; // '일십' 대신 '십'
  });
  return s;
}

const HOURS = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열", "열한", "열두"]; // 시각은 고유어로 읽음

function readHour(n: number): string {
  // 시각: 3시 → 세 시, 12시 → 열두 시 (1~12는 고유어, 그 밖은 한자어)
  return (n >= 1 && n <= 12 ? HOURS[n] : num2kor(n)) + " 시";
}

function readMonth(n: number): string {
  // 달: 6월 → 유월, 10월 → 시월 (받침이 떨어지는 예외), 나머지는 한자어 + 월
  return n === 6 ? "유월" : n === 10 ? "시월" : num2kor(n) + "월";
}
const TERMS: Record<string, string> = { whisper: "위스퍼", api: "에이피아이", cer: "씨이알", pyannote: "파이아노트" }; // 바꿔 보기: 우리 회사 용어

function normalize(s: string): string {
  // 채점 전 정규화: 소문자 → 문장 부호 → 숫자를 한글로 → 용어 사전 → 공백 정리
  s = s.toLowerCase(); // ① 소문자
  s = s.replace(/(?<=\d),(?=\d)/g, ""); //    2,500 → 2500 (숫자 속 쉼표)
  s = s.replace(/[^\p{L}\p{N}_\s]/gu, " "); // ① 문장 부호 → 공백
  s = s.replace(/(\d+)\s*시/g, (_, n: string) => readHour(Number(n))); // ② 시각: 3시 → 세 시
  s = s.replace(/(\d+)\s*월/g, (_, n: string) => readMonth(Number(n))); // ② 달: 10월 → 시월
  s = s.replace(/\d+/g, (m) => num2kor(Number(m))); // ② 나머지 숫자 → 한글
  for (const [k, v] of Object.entries(TERMS)) s = s.replaceAll(k, v); // ③ 용어 사전
  return s.replace(/\s+/g, " ").trim(); // ④ 공백 정리
}
type Turn = { speaker: string; text: string; start: number; end: number };
type Seg = { start: number; end: number; speaker: string };
type Line = { speaker: string; start: number; end: number; text: string; name?: string };
type ActionItem = { owner: string; task: string; due: string };
type Summary = { summary: string[]; decisions: string[]; action_items: ActionItem[] };
// 회의 녹음 만들기: Node 내장만으로는 진짜 목소리를 못 만들어서 사람마다 음높이가 다른 합성 신호로 대신 (Python 버전은 edge-tts)
const VOICES: Record<string, number> = { 김팀장: 110, 이연구원: 220, 박대리: 150 }; // 이름 → 기본 음높이(Hz)
const SCRIPT: Array<[string, string]> = [
  ["김팀장", "오늘은 회의록 생성기 개발 일정을 정하겠습니다."],
  ["이연구원", "받아쓰기는 위스퍼 스몰 모델을 그대로 쓰기로 했습니다."],
  ["박대리", "화자 분리는 파이아노트를 쓰고, 토큰이 없으면 직접 만든 방법을 쓰겠습니다."],
  ["김팀장", "좋습니다. 그렇게 결정하겠습니다."],
  ["이연구원", "평가는 정규화를 한 뒤에 글자 오류율로 하겠습니다."],
  ["박대리", "저는 수요일까지 단어 시각 정렬을 붙이겠습니다."],
  ["이연구원", "저는 목요일까지 평가 스크립트를 만들겠습니다."],
  ["김팀장", "그럼 금요일 오후에 결과를 같이 검토합시다."],
];

function makeMeeting(): { meeting: Float32Array; turns: Turn[]; enroll: Record<string, Float32Array> } {
  // → 회의 녹음, 정답 발화 구간(turns), 화자 등록 음성(enroll)
  const rnd = mulberry32(0);
  const pieces: Float32Array[] = [new Float32Array(Math.floor(0.5 * SR))];
  const turns: Turn[] = [];
  let t = 0.5;
  SCRIPT.forEach(([name, text], i) => {
    const y = synthVoice(Math.max(1, text.length * 0.12), VOICES[name], i + 1);
    turns.push({ speaker: name, text, start: t, end: t + y.length / SR });
    const gap = 0.5 + 0.4 * rnd(); // 발화 사이 쉼 0.5~0.9초
    pieces.push(y, new Float32Array(Math.floor(gap * SR)));
    t += y.length / SR + gap;
  });
  const meeting = new Float32Array(pieces.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of pieces) {
    meeting.set(p, at);
    at += p.length;
  }
  const enroll: Record<string, Float32Array> = {};
  Object.entries(VOICES).forEach(([name, f0], i) => (enroll[name] = synthVoice(3, f0, 100 + i)));
  return { meeting, turns, enroll };
}
const REF_MEETING = SCRIPT.map(([, t]) => t).join(" "); // 회의 대본 전체 = 받아쓰기 정답

// R2 · R3: 화자 분리 · 줄 만들기 (수업 노트북의 pyannote·SpeechBrain 대신 로그 멜 특징 + 평균 연결 군집)
function embed(y: Float32Array): number[] {
  // 화자 특징(간단 버전): 로그 멜 80칸의 시간 평균에서 자기 평균을 뺀 '소리 모양'
  const S = logMel(y, SR);
  const mean = new Array<number>(N_MELS).fill(0);
  for (const f of S) f.forEach((v, k) => (mean[k] += v / Math.max(1, S.length)));
  const mu = mean.reduce((a, b) => a + b, 0) / N_MELS;
  return mean.map((v) => v - mu);
}

function zscore(E: number[][]): number[][] {
  // 특징마다 평균 0 · 표준편차 1 (표준편차가 0이면 나누지 않음)
  const dim = E[0].length;
  const mu = Array.from({ length: dim }, (_, k) => E.reduce((a, e) => a + e[k], 0) / E.length);
  const sd = Array.from({ length: dim }, (_, k) => Math.sqrt(E.reduce((a, e) => a + (e[k] - mu[k]) ** 2, 0) / E.length));
  return E.map((e) => e.map((v, k) => (v - mu[k]) / (sd[k] > 1e-9 ? sd[k] : 1)));
}

function cosine(a: number[], b: number[]): number {
  let ab = 0;
  let aa = 0;
  let bb = 0;
  a.forEach((v, k) => {
    ab += v * b[k];
    aa += v * v;
    bb += b[k] * b[k];
  });
  return ab / Math.max(Math.sqrt(aa * bb), 1e-9);
}

function cluster(E: number[][], k: number | null, threshold: number = 0.6): number[] {
  // 평균 연결 군집: 가장 가까운(코사인 거리) 두 무리를 합치기를 k개가 될 때까지(또는 거리가 threshold를 넘을 때까지)
  let groups = E.map((_, i) => [i]);
  const link = (A: number[], B: number[]): number => A.reduce((s, a) => s + B.reduce((t, b) => t + 1 - cosine(E[a], E[b]), 0), 0) / (A.length * B.length);
  while (groups.length > 1 && (k === null || groups.length > k)) {
    let best: [number, number, number] = [0, 1, Infinity];
    for (let i = 0; i < groups.length; i++) for (let j = i + 1; j < groups.length; j++) {
      const d = link(groups[i], groups[j]);
      if (d < best[2]) best = [i, j, d];
    }
    if (k === null && best[2] > threshold) break;
    groups[best[0]] = groups[best[0]].concat(groups[best[1]]);
    groups = groups.filter((_, i) => i !== best[1]);
  }
  const labels = new Array<number>(E.length).fill(0);
  groups.sort((A, B) => Math.min(...A) - Math.min(...B)).forEach((g, c) => g.forEach((i) => (labels[i] = c)));
  return labels;
}

function diarize(y: Float32Array, numSpeakers: number | null = null): Seg[] {
  // R2: 소리 구간 나누기 → 구간마다 특징 → 군집으로 화자 번호 붙이기
  const segs = speechSegments(y);
  if (segs.length < 2) return segs.map(([a, b]) => ({ start: a, end: b, speaker: "SPEAKER_00" }));
  const E = zscore(segs.map(([a, b]) => embed(y.subarray(Math.floor(a * SR), Math.floor(b * SR)))));
  const labels = cluster(E, numSpeakers ? Math.min(numSpeakers, segs.length) : null); // 바꿔 보기: threshold
  return segs.map(([a, b], i) => ({ start: a, end: b, speaker: `SPEAKER_${String(labels[i]).padStart(2, "0")}` }));
}

function speakerAt(diar: Seg[], t0: number, t1: number): string {
  // 단어 구간과 가장 많이 겹치는 화자, 겹치는 게 없으면 가장 가까운 구간의 화자
  if (diar.length === 0) return "?";
  const ov = diar.map((d) => Math.min(t1, d.end) - Math.max(t0, d.start));
  const top = Math.max(...ov);
  if (top > 0) return diar[ov.indexOf(top)].speaker;
  const mid = (t0 + t1) / 2;
  const gap = diar.map((d) => Math.min(Math.abs(mid - d.start), Math.abs(mid - d.end)));
  return diar[gap.indexOf(Math.min(...gap))].speaker;
}

function toLines(words: Word[], diar: Seg[]): Line[] {
  // R3: 단어에 화자를 붙이고, 같은 화자가 이어 말하면 한 줄로 합친다
  // 받아쓰기 단어가 없으면(키 없음) 화자 분리 구간만으로 줄을 만든다
  const items: Word[] = words.length ? words : diar.map((d) => ({ word: "(받아쓰기 생략)", start: d.start, end: d.end }));
  const lines: Line[] = [];
  for (const w of items) {
    const spk = (w.speaker = speakerAt(diar, w.start, w.end));
    const last = lines[lines.length - 1];
    if (last && last.speaker === spk) {
      if (words.length) last.text += " " + w.word;
      last.end = w.end;
    } else lines.push({ speaker: spk, start: w.start, end: w.end, text: w.word });
  }
  return lines;
}

function nameSpeakers(y: Float32Array, diar: Seg[], enroll: Record<string, Float32Array> | null = null): Record<string, string> {
  // 화자 번호 → 이름: 등록 음성과 특징이 가장 닮은 사람끼리 1:1로 짝짓기 (사람 수가 적어 모든 짝을 다 따져 봄)
  const labs = [...new Set(diar.map((d) => d.speaker))].sort();
  const same: Record<string, string> = Object.fromEntries(labs.map((l) => [l, l]));
  if (!enroll || labs.length === 0) return same;
  const names = Object.keys(enroll);
  const clips = labs.map((l) => {
    const parts = diar.filter((d) => d.speaker === l).map((d) => y.subarray(Math.floor(d.start * SR), Math.floor(d.end * SR)));
    const out = new Float32Array(Math.min(SR * 20, parts.reduce((n, p) => n + p.length, 0)));
    let at = 0;
    for (const p of parts) {
      if (at >= out.length) break;
      out.set(p.subarray(0, out.length - at), at);
      at += Math.min(p.length, out.length - at);
    }
    return out;
  });
  const E = zscore([...clips.map(embed), ...names.map((n) => embed(enroll[n]))]);
  const sim = labs.map((_, i) => names.map((_, j) => cosine(E[i], E[labs.length + j])));
  let best: number[] = [];
  let bestScore = -Infinity;
  const pick = (i: number, used: number[], score: number): void => { // i번째 화자 번호에 이름 하나씩 (-1 = 이름 없음)
    if (i === labs.length) {
      if (score > bestScore) [best, bestScore] = [used.slice(), score];
      return;
    }
    for (let j = -1; j < names.length; j++) {
      if (j >= 0 && used.includes(j)) continue;
      if (j < 0 && labs.length <= names.length) continue; // 이름이 충분하면 모두 짝짓기
      pick(i + 1, [...used, j], score + (j >= 0 ? sim[i][j] : 0));
    }
  };
  pick(0, [], 0);
  return Object.fromEntries(labs.map((l, i) => [l, best[i] >= 0 ? names[best[i]] : l]));
}
function fmtTime(t: number): string {
  // 초 → '분:초' (예: 205 → 03:25)
  return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(Math.floor(t % 60)).padStart(2, "0")}`;
}
const SYSTEM = "당신은 한국어 회의록을 정리하는 비서입니다. 녹취에 없는 내용은 절대 지어내지 않습니다.";
const MODEL = "claude-haiku-5-5"; // 바꿔 보기: 더 꼼꼼한 요약은 "claude-sonnet-5-5"

function buildPrompt(transcript: string): string {
  return `아래는 음성 인식으로 만든 회의 녹취입니다. 받아쓰기 오류가 있을 수 있으니 문맥으로 이해하세요.

<녹취>
${transcript}
</녹취>

다음 JSON 형식으로만 답하세요. 다른 말은 쓰지 마세요.
{"summary": ["요약 문장 (3개 이내)"],
 "decisions": ["결정된 사항"],
 "action_items": [{"owner": "담당자 이름", "task": "할 일", "due": "기한 (말하지 않았으면 빈 문자열)"}]}

규칙: 녹취에 없는 내용은 쓰지 않습니다. 담당자와 기한은 녹취에서 말한 그대로 씁니다.`;
}

const DAYS = ["월요일", "화요일", "수요일", "목요일", "금요일", "다음 주", "오늘", "내일"];

function ruleBasedSummary(lines: Line[]): Summary {
  // 키 없이 쓰는 규칙 기반 요약: 결정 낱말 · 요일이 든 문장을 골라낸다
  const decisions: string[] = [];
  const actions: ActionItem[] = [];
  for (const ln of lines) {
    for (const t of ln.text.split(/(?<=[.?!])\s+/)) { // 한 줄을 문장으로 나눠서 봄
      if (["결정", "정했", "쓰기로", "하기로"].some((k) => t.includes(k))) decisions.push(t);
      const due = DAYS.find((d) => t.includes(d)) ?? "";
      if (due && ["겠습니다", "합시다", "까지"].some((k) => t.includes(k))) actions.push({ owner: ln.name ?? ln.speaker, task: t, due });
    }
  }
  const people = new Set(lines.map((l) => l.name ?? l.speaker));
  return {
    summary: [`발언 ${lines.length}건, 참석자 ${people.size}명`, `결정 사항 ${decisions.length}건, 할 일 ${actions.length}건`],
    decisions,
    action_items: actions,
  };
}

function parseJson(text: string): Summary {
  // LLM 답에서 JSON 꺼내기: ```json ... ``` 떼어 내고, 키가 없거나 모양이 다르면 빈 목록
  text = text.trim();
  if (text.startsWith("```")) text = text.slice(text.indexOf("\n") + 1, text.lastIndexOf("```"));
  const data: unknown = JSON.parse(text);
  const obj = isRecord(data) ? data : {};
  const strs = (v: unknown): string[] => (Array.isArray(v) ? v.map(String) : []);
  const items: unknown[] = Array.isArray(obj.action_items) ? obj.action_items : [];
  return {
    summary: strs(obj.summary),
    decisions: strs(obj.decisions),
    action_items: items.map((a) => // 할 일이 문자열이면 task로
      isRecord(a) ? { owner: String(a.owner ?? ""), task: String(a.task ?? ""), due: String(a.due ?? "") } : { owner: "", task: String(a), due: "" }),
  };
}

async function summarize(lines: Line[], transcript: string): Promise<[Summary, string]> {
  // R4: ANTHROPIC_API_KEY가 있으면 Claude, 없거나 실패하면 규칙 기반 → [요약, 방법]
  if (process.env.ANTHROPIC_API_KEY) {
    try {
      return [parseJson(await callClaude(SYSTEM, buildPrompt(transcript), MODEL, 1500)), "Claude"];
    } catch (e) {
      console.log(`[주의] LLM 요약 실패 → 규칙 기반으로 대신: ${String(e).slice(0, 120)}`);
    }
  }
  return [ruleBasedSummary(lines), "규칙 기반"];
}

function renderMinutes(summary: Summary, lines: Line[], title: string = "회의록 (자동 생성)"): string {
  const md = [`# ${title}`, "", "## 요약", ...summary.summary.map((s) => `- ${s}`)];
  md.push("", "## 결정 사항", ...(summary.decisions.length ? summary.decisions.map((d) => `- ${d}`) : ["- (없음)"]));
  md.push("", "## 할 일", "| 담당 | 할 일 | 기한 |", "|---|---|---|");
  md.push(...(summary.action_items.length ? summary.action_items.map((a) => `| ${a.owner} | ${a.task} | ${a.due} |`) : ["| - | - | - |"]));
  md.push("", "## 녹취", ...(lines.length ? lines.map((l) => `- **[${fmtTime(l.start)}] ${l.name ?? l.speaker}**: ${l.text}`) : ["- (인식된 말 없음)"]));
  return md.join("\n");
}
const KEY_POINTS: Record<string, string[]> = { // 핵심 사항: 이 중 하나라도 나오면 '담음'
  "받아쓰기 모델 = 위스퍼 스몰": ["위스퍼", "whisper"],
  "화자 분리 = 파이아노트": ["파이아노트", "pyannote"],
  "평가 = 정규화 후 글자 오류율": ["오류율", "cer"],
  "박대리 · 수요일 · 단어 시각 정렬": ["수요일"],
  "이연구원 · 목요일 · 평가 스크립트": ["목요일"],
};

function turnOf(turns: Turn[], t: number): number {
  // 시각 t가 속한(없으면 가장 가까운) 정답 발화 번호
  const d = turns.map((x) => (x.start <= t && t <= x.end ? 0 : Math.min(Math.abs(t - x.start), Math.abs(t - x.end))));
  return d.indexOf(Math.min(...d));
}

function evaluate(summary: Summary, how: string, words: Word[], name: Record<string, string>, turns: Turn[], refText: string): number {
  // 평가표: 받아쓰기 CER(정규화 전·후) · 단어별 화자 정확도 · 요약 핵심 사항 점검 → 요약 점수(0~1)
  const summaryText = normalize(JSON.stringify(summary));
  const found = Object.entries(KEY_POINTS).map(([k, kws]): [string, boolean] => [k, kws.some((w) => summaryText.includes(normalize(w)))]);
  const hit = found.filter(([, v]) => v).length;

  const hypText = words.map((w) => w.word).join(" ");
  const hits = words.map((w) => (name[w.speaker ?? "?"] ?? "?") === turns[turnOf(turns, (w.start + w.end) / 2)].speaker);
  const spkAcc = hits.length ? hits.filter(Boolean).length / hits.length : 0; // 단어가 없으면 0 (0 나누기 방지)

  console.log("평가표");
  console.log(`  받아쓰기 CER   정규화 전 ${(cer(refText, hypText) * 100).toFixed(1)}% → 정규화 후 ${(cer(normalize(refText), normalize(hypText)) * 100).toFixed(1)}%`);
  console.log(`  단어별 화자 정확도 ${(spkAcc * 100).toFixed(1)}% (단어 ${words.length}개)`);
  console.log(`  요약 점검 ${hit}/${found.length} (${how})`);
  for (const [k, v] of found) console.log(`    [${v ? "O" : " "}] ${k}`);
  return hit / Object.keys(KEY_POINTS).length;
}
type Minutes = { md: string; summary: Summary; words: Word[]; name: Record<string, string>; how: string; engine: string };

async function makeMinutes(wavPath: string, numSpeakers: number | null = null, enroll: Record<string, Float32Array> | null = null): Promise<Minutes> {
  // 녹음 파일 하나 → 회의록 마크다운 (R1 받아쓰기 → R2 화자 분리 → R3 줄 → 이름 → R4 요약)
  const { y } = readWav(wavPath);
  const heard = await transcribe(wavPath); // R1 (OPENAI_API_KEY 없으면 단어 없이 진행)
  const diar = diarize(y, numSpeakers); // R2
  const lines = toLines(heard.words, diar); // R3
  const name = nameSpeakers(y, diar, enroll);
  for (const ln of lines) ln.name = name[ln.speaker] ?? ln.speaker;
  const transcript = lines.map((l) => `[${fmtTime(l.start)}] ${l.name}: ${l.text}`).join("\n");
  const [summary, how] = await summarize(lines, transcript); // R4
  const md = renderMinutes(summary, lines, `회의록 (자동 생성 · 받아쓰기: ${heard.engine} · 요약: ${how})`);
  return { md, summary, words: heard.words, name, how, engine: heard.engine };
}
