// D10 · Part 1 · 편집 거리 표 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d10_editdist.ts

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
function editDistance<T>(r: T[], h: T[]): number[][] {
  // 편집 거리 표: d[i][j] = 정답 앞 i개를 결과 앞 j개로 바꾸는 최소 고침 횟수
  const n = r.length;
  const m = h.length;
  const d = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));
  for (let i = 0; i <= n; i++) d[i][0] = i; // 결과가 비었으면 정답을 모두 '빠짐'
  for (let j = 0; j <= m; j++) d[0][j] = j; // 정답이 비었으면 결과가 모두 '끼어듦'
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      const cost = r[i - 1] === h[j - 1] ? 0 : 1;
      d[i][j] = Math.min(
        d[i - 1][j] + 1, // 빠짐 (D)
        d[i][j - 1] + 1, // 끼어듦 (I)
        d[i - 1][j - 1] + cost, // 같음(0) 또는 바꿈 (S)
      );
    }
  }
  return d;
}

const corner = (d: number[][]): number => d[d.length - 1][d[0].length - 1]; // 오른쪽 아래 칸 = 최소 고침 횟수
const ref = "회의를 세 시에 시작합니다".split(" ");
const hyp = "회의를 3시에 바로 시작합니다".split(" ");
const d = editDistance(ref, hyp);
console.table(Object.fromEntries(d.map((row, i) => [i ? ref[i - 1] : "-", Object.fromEntries(row.map((v, j) => [j ? hyp[j - 1] : "-", v]))])));
console.log("\n최소 고침 횟수 =", corner(d));
check(corner(d) === 2 && corner(editDistance([..."abc"], [..."abd"])) === 1, "두 단어가 같으면 0, 다르면 1인 변수 cost 입니다.");

