# D10 · Part 1 · WER · CER — 단독 실행 완성 코드 (Python 3.11)
# pip install jiwer==4.0.0 numpy==2.4.6
# 실행: python d10_wercer.py   (직접 만든 WER·CER과 jiwer 값이 같은지 비교 · 인터넷 불필요)
import jiwer
import numpy as np

def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")
def edit_distance(r: list, h: list) -> np.ndarray:
    """편집 거리 표: d[i, j] = 정답 앞 i개를 결과 앞 j개로 바꾸는 최소 고침 횟수."""
    n, m = len(r), len(h)
    d = np.zeros((n + 1, m + 1), dtype=int)
    d[:, 0] = np.arange(n + 1)                      # 결과가 비었으면 정답을 모두 '빠짐'
    d[0, :] = np.arange(m + 1)                      # 정답이 비었으면 결과가 모두 '끼어듦'
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cost = 0 if r[i - 1] == h[j - 1] else 1
            d[i, j] = min(d[i - 1, j] + 1,           # 빠짐 (D)
                          d[i, j - 1] + 1,           # 끼어듦 (I)
                          d[i - 1, j - 1] + cost)    # 같음(0) 또는 바꿈 (S)
    return d
def error_rate(r: list, h: list) -> float:
    """오류율 = 최소 고침 횟수 ÷ 정답 길이 (정답이 비면 0으로 나누게 되므로 오류)."""
    if not r:
        raise ValueError("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요")
    return edit_distance(r, h)[-1, -1] / len(r)


def my_wer(ref: str, hyp: str) -> float:
    return error_rate(ref.split(), hyp.split())


def my_cer(ref: str, hyp: str) -> float:
    return error_rate(list(ref), list(hyp))                 # 공백도 한 글자로 셈 (jiwer와 같음)
pairs = [("회의를 세 시에 시작합니다", "회의를 3시에 바로 시작합니다"),
         ("회의록 생성기를 만들어 봅시다", "회의록생성기를 만들어봅시다"),
         ("네 좋습니다", "네 네 네 좋습니다 감사합니다")]
for r, h in pairs:
    print(f"정답: {r}\n결과: {h}")
    print(f"  WER 직접 {my_wer(r, h):6.1%} | jiwer {jiwer.wer(r, h):6.1%}   ·   CER 직접 {my_cer(r, h):6.1%} | jiwer {jiwer.cer(r, h):6.1%}\n")
check(all(abs(my_wer(r, h) - jiwer.wer(r, h)) < 1e-9 and abs(my_cer(r, h) - jiwer.cer(r, h)) < 1e-9 for r, h in pairs),
      hint="분모는 정답의 길이 len(r) 입니다.")

wercer.typescript:
// D10 · Part 1 · WER · CER — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d10_wercer.ts
// 편집 거리 표로 직접 만든 WER·CER과, 한 줄씩만 들고 계산하는 cer·wer(jiwer와 같은 방식)가 같은지 비교해요.

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
function editDistance<T>(r: T[], h: T[]): number[][] {
  // 편집 거리 표: d[i][j] = 정답 앞 i개를 결과 앞 j개로 바꾸는 최소 고침 횟수
  const n = r.length;
  const m = h.length;
  const d = Array.from({ length: n + 1 }, () => new Array<number>(m + 1).fill(0));
  for (let i = 0; i <= n; i++) d[i][0] = i; // 결과가 비었으면 정답을 모두 '빠짐'
  for (let j = 0; j <= m; j++) d[0][j] = j; // 정답이 비었으면 결과가 모두 '끼어듦'
  for (let i = 1; i <= n; i++) {
    for (let j = 1; j <= m; j++) {
      const cost = r[i - 1] === h[j - 1] ? 0 : 1;
      d[i][j] = Math.min(
        d[i - 1][j] + 1, // 빠짐 (D)
        d[i][j - 1] + 1, // 끼어듦 (I)
        d[i - 1][j - 1] + cost, // 같음(0) 또는 바꿈 (S)
      );
    }
  }
  return d;
}

const corner = (d: number[][]): number => d[d.length - 1][d[0].length - 1]; // 오른쪽 아래 칸 = 최소 고침 횟수
function errorRate<T>(r: T[], h: T[]): number {
  // 오류율 = 최소 고침 횟수 ÷ 정답 길이 (정답이 비면 0으로 나누게 되므로 오류)
  if (r.length === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return corner(editDistance(r, h)) / r.length;
}

const myWer = (ref: string, hyp: string): number => errorRate(ref.split(" ").filter(Boolean), hyp.split(" ").filter(Boolean));
const myCer = (ref: string, hyp: string): number => errorRate([...ref], [...hyp]); // 공백도 한 글자로 셈
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
function wer(ref: string | string[], hyp: string | string[]): number {
  // 단어 오류율 (jiwer.wer와 같은 방식: 공백으로 단어를 나눔)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  const split = (s: string): string[] => s.trim().split(/\s+/).filter(Boolean);
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rw = split(r);
    edits += editCount(rw, split(H[i] ?? ""));
    total += rw.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
const pairs: Array<[string, string]> = [
  ["회의를 세 시에 시작합니다", "회의를 3시에 바로 시작합니다"],
  ["회의록 생성기를 만들어 봅시다", "회의록생성기를 만들어봅시다"],
  ["네 좋습니다", "네 네 네 좋습니다 감사합니다"],
];
const pct = (v: number): string => `${(v * 100).toFixed(1)}%`.padStart(6);
for (const [r, h] of pairs) {
  console.log(`정답: ${r}\n결과: ${h}`);
  console.log(`  WER 직접 ${pct(myWer(r, h))} | 한 줄 계산 ${pct(wer(r, h))}   ·   CER 직접 ${pct(myCer(r, h))} | 한 줄 계산 ${pct(cer(r, h))}\n`);
}
// Python jiwer 4.0.0이 같은 문장에 낸 값: WER 50% · 100% · 150%, CER 35.7%(5/14) · 12.5%(2/16) · 166.7%(10/6)
check(
  pairs.every(([r, h]) => Math.abs(myWer(r, h) - wer(r, h)) < 1e-9 && Math.abs(myCer(r, h) - cer(r, h)) < 1e-9) && Math.abs(myWer(...pairs[0]) - 0.5) < 1e-9,
  "분모는 정답의 길이 r.length 입니다.",
);

