// D10 · Part 2 · 한국어 정규화와 CER — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d10_norm.ts   → 비교 막대 그림 cer_compare.svg 저장
// 받아쓰기 결과는 코드 안의 예시(HYPS)를 써요. (Python 버전은 edge-tts로 읽고 faster-whisper로 받아써요)
import { writeFileSync } from "node:fs";

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
function wer(ref: string | string[], hyp: string | string[]): number {
  // 단어 오류율 (jiwer.wer와 같은 방식: 공백으로 단어를 나눔)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  const split = (s: string): string[] => s.trim().split(/\s+/).filter(Boolean);
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rw = split(r);
    edits += editCount(rw, split(H[i] ?? ""));
    total += rw.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
const DIG = "영일이삼사오육칠팔구";
const UNITS = ["", "십", "백", "천"];

function num2kor(n: number): string {
  // 0~9999를 한글 읽기로: 2026 → 이천이십육 (만 이상은 그대로 둔다)
  if (n === 0) return "영";
  if (n >= 10000) return String(n);
  let s = "";
  [...String(n)].reverse().forEach((ch, i) => { // i = 0(일의 자리), 1(십), 2(백), 3(천)
    const d = Number(ch);
    if (d === 0) return;
    s = (d === 1 && i > 0 ? "" : DIG[d]) + UNITS[i] + s; // '일십' 대신 '십'
  });
  return s;
}

const HOURS = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열", "열한", "열두"]; // 시각은 고유어로 읽음

function readHour(n: number): string {
  // 시각: 3시 → 세 시, 12시 → 열두 시 (1~12는 고유어, 그 밖은 한자어)
  return (n >= 1 && n <= 12 ? HOURS[n] : num2kor(n)) + " 시";
}

function readMonth(n: number): string {
  // 달: 6월 → 유월, 10월 → 시월 (받침이 떨어지는 예외), 나머지는 한자어 + 월
  return n === 6 ? "유월" : n === 10 ? "시월" : num2kor(n) + "월";
}
const TERMS: Record<string, string> = { whisper: "위스퍼", api: "에이피아이", cer: "씨이알", pyannote: "파이아노트" }; // 바꿔 보기: 우리 회사 용어

function normalize(s: string): string {
  // 채점 전 정규화: 소문자 → 문장 부호 → 숫자를 한글로 → 용어 사전 → 공백 정리
  s = s.toLowerCase(); // ① 소문자
  s = s.replace(/(?<=\d),(?=\d)/g, ""); //    2,500 → 2500 (숫자 속 쉼표)
  s = s.replace(/[^\p{L}\p{N}_\s]/gu, " "); // ① 문장 부호 → 공백
  s = s.replace(/(\d+)\s*시/g, (_, n: string) => readHour(Number(n))); // ② 시각: 3시 → 세 시
  s = s.replace(/(\d+)\s*월/g, (_, n: string) => readMonth(Number(n))); // ② 달: 10월 → 시월
  s = s.replace(/\d+/g, (m) => num2kor(Number(m))); // ② 나머지 숫자 → 한글
  for (const [k, v] of Object.entries(TERMS)) s = s.replaceAll(k, v); // ③ 용어 사전
  return s.replace(/\s+/g, " ").trim(); // ④ 공백 정리
}
const REFS = [
  "회의는 오후 3시에 시작합니다.",
  "Whisper 모델로 받아쓰기를 했습니다.",
  "다음 주까지 API 문서를 정리해 주세요.",
  "예산은 2500만 원으로 정했습니다.",
  "10월 20일에 결과를 공유하겠습니다.",
  "음성 인식 정확도를 CER로 평가합니다.",
];
const HYPS = [ // 받아쓰기 결과 예시 (같은 뜻, 다른 표기)
  "회의는 오후 세 시에 시작합니다",
  "위스퍼 모델로 받아쓰기를 했습니다",
  "다음 주까지 에이피아이 문서를 정리해주세요",
  "예산은 2,500만원으로 정했습니다",
  "시월 이십일에 결과를 공유하겠습니다",
  "음성인식 정확도를 씨이알로 평가합니다",
];
const pct = (v: number): string => `${(v * 100).toFixed(1)}%`;

console.log(`정규화 전: WER ${pct(wer(REFS, HYPS))} · CER ${pct(cer(REFS, HYPS))}\n`);

for (const n of [3, 10, 20, 2500, 2026, 1001]) console.log(n, "→", num2kor(n));
console.log("3시 →", readHour(3), "| 12시 →", readHour(12), "| 6월 →", readMonth(6), "| 10월 →", readMonth(10));
for (const r of REFS.slice(0, 4)) console.log(`${r}  →  ${normalize(r)}`);
check(normalize("Whisper로  10월 20일, API!") === "위스퍼로 시월 이십일 에이피아이", "용어 사전은 v, 공백 정리는 공백 한 칸 \" \" 입니다.");

const rows = REFS.map((r, i) => {
  const [nr, nh] = [normalize(r), normalize(HYPS[i])];
  return { 정답: r, 결과: HYPS[i], CER_전: +cer(r, HYPS[i]).toFixed(3), CER_후: +cer(nr, nh).toFixed(3), CER_공백무시: +cer(nr.replaceAll(" ", ""), nh.replaceAll(" ", "")).toFixed(3) };
});
console.table(rows);

const NR = REFS.map(normalize);
const NH = HYPS.map(normalize);
const nospace = (xs: string[]): string[] => xs.map((x) => x.replaceAll(" ", ""));
const tot: Record<string, number> = { raw: cer(REFS, HYPS), normalized: cer(NR, NH), "normalized, no space": cer(nospace(NR), nospace(NH)) };
console.log("\n전체 CER:", Object.fromEntries(Object.entries(tot).map(([k, v]) => [k, pct(v)])), "| WER 정규화 후:", pct(wer(NR, NH)));

const colors = ["gray", "purple", "hotpink"];
const bars = Object.entries(tot).map(([k, v], i) => `<text x="0" y="${i * 30 + 20}" font-size="12">${k}</text><rect x="150" y="${i * 30 + 6}" width="${v * 400}" height="20" fill="${colors[i]}"/><text x="${155 + v * 400}" y="${i * 30 + 20}" font-size="12">${pct(v)}</text>`);
writeFileSync("cer_compare.svg", `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 100">${bars.join("")}</svg>`);
console.log("그림 저장: cer_compare.svg");

