}
type Turn = { speaker: string; text: string; start: number; end: number };
type Seg = { start: number; end: number; speaker: string };
type Line = { speaker: string; start: number; end: number; text: string; name?: string };

// 회의 녹음 만들기: Node 내장만으로는 진짜 목소리를 못 만들어서 사람마다 음높이가 다른 합성 신호로 대신 (Python 버전은 edge-tts)
const VOICES: Record<string, number> = { 김팀장: 110, 이연구원: 220, 박대리: 150 }; // 이름 → 기본 음높이(Hz)
const SCRIPT: Array<[string, string]> = [
