  ["박대리", "화자 분리는 파이아노트를 쓰고, 토큰이 없으면 직접 만든 방법을 쓰겠습니다."],
  ["김팀장", "좋습니다. 그렇게 결정하겠습니다."],
  ["이연구원", "평가는 정규화를 한 뒤에 글자 오류율로 하겠습니다."],
  ["박대리", "저는 수요일까지 단어 시각 정렬을 붙이겠습니다."],
  ["이연구원", "저는 목요일까지 평가 스크립트를 만들겠습니다."],
  ["김팀장", "그럼 금요일 오후에 결과를 같이 검토합시다."],
];

function makeMeeting(): { meeting: Float32Array; turns: Turn[]; enroll: Record<string, Float32Array> } {
  // → 회의 녹음, 정답 발화 구간(turns), 화자 등록 음성(enroll)
  const rnd = mulberry32(0);
  const pieces: Float32Array[] = [new Float32Array(Math.floor(0.5 * SR))];
  const turns: Turn[] = [];
  let t = 0.5;
  SCRIPT.forEach(([name, text], i) => {
    const y = synthVoice(Math.max(1, text.length * 0.12), VOICES[name], i + 1);
    turns.push({ speaker: name, text, start: t, end: t + y.length / SR });
    const gap = 0.5 + 0.4 * rnd(); // 발화 사이 쉼 0.5~0.9초
    pieces.push(y, new Float32Array(Math.floor(gap * SR)));
    t += y.length / SR + gap;
  });
  const meeting = new Float32Array(pieces.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of pieces) {
    meeting.set(p, at);
    at += p.length;
  }
  const enroll: Record<string, Float32Array> = {};
  Object.entries(VOICES).forEach(([name, f0], i) => (enroll[name] = synthVoice(3, f0, 100 + i)));
  return { meeting, turns, enroll };
}
// R2 · R3: 화자 분리 · 줄 만들기 (수업 노트북의 pyannote·SpeechBrain 대신 로그 멜 특징 + 평균 연결 군집)
function embed(y: Float32Array): number[] {
  // 화자 특징(간단 버전): 로그 멜 80칸의 시간 평균에서 자기 평균을 뺀 '소리 모양'
  const S = logMel(y, SR);
  const mean = new Array<number>(N_MELS).fill(0);
  for (const f of S) f.forEach((v, k) => (mean[k] += v / Math.max(1, S.length)));
  const mu = mean.reduce((a, b) => a + b, 0) / N_MELS;
  return mean.map((v) => v - mu);
}

function zscore(E: number[][]): number[][] {
  // 특징마다 평균 0 · 표준편차 1 (표준편차가 0이면 나누지 않음)
  const dim = E[0].length;
  const mu = Array.from({ length: dim }, (_, k) => E.reduce((a, e) => a + e[k], 0) / E.length);
  const sd = Array.from({ length: dim }, (_, k) => Math.sqrt(E.reduce((a, e) => a + (e[k] - mu[k]) ** 2, 0) / E.length));
  return E.map((e) => e.map((v, k) => (v - mu[k]) / (sd[k] > 1e-9 ? sd[k] : 1)));
}

function cosine(a: number[], b: number[]): number {
  let ab = 0;
  let aa = 0;
  let bb = 0;
  a.forEach((v, k) => {
    ab += v * b[k];
    aa += v * v;
    bb += b[k] * b[k];
  });
  return ab / Math.max(Math.sqrt(aa * bb), 1e-9);
}

function cluster(E: number[][], k: number | null, threshold: number = 0.6): number[] {
  // 평균 연결 군집: 가장 가까운(코사인 거리) 두 무리를 합치기를 k개가 될 때까지(또는 거리가 threshold를 넘을 때까지)
  let groups = E.map((_, i) => [i]);
  const link = (A: number[], B: number[]): number => A.reduce((s, a) => s + B.reduce((t, b) => t + 1 - cosine(E[a], E[b]), 0), 0) / (A.length * B.length);
  while (groups.length > 1 && (k === null || groups.length > k)) {
    let best: [number, number, number] = [0, 1, Infinity];
    for (let i = 0; i < groups.length; i++) for (let j = i + 1; j < groups.length; j++) {
      const d = link(groups[i], groups[j]);
      if (d < best[2]) best = [i, j, d];
    }
    if (k === null && best[2] > threshold) break;
    groups[best[0]] = groups[best[0]].concat(groups[best[1]]);
    groups = groups.filter((_, i) => i !== best[1]);
  }
  const labels = new Array<number>(E.length).fill(0);
  groups.sort((A, B) => Math.min(...A) - Math.min(...B)).forEach((g, c) => g.forEach((i) => (labels[i] = c)));
  return labels;
}

function diarize(y: Float32Array, numSpeakers: number | null = null): Seg[] {
  // R2: 소리 구간 나누기 → 구간마다 특징 → 군집으로 화자 번호 붙이기
  const segs = speechSegments(y);
  if (segs.length < 2) return segs.map(([a, b]) => ({ start: a, end: b, speaker: "SPEAKER_00" }));
  const E = zscore(segs.map(([a, b]) => embed(y.subarray(Math.floor(a * SR), Math.floor(b * SR)))));
  const labels = cluster(E, numSpeakers ? Math.min(numSpeakers, segs.length) : null); // 바꿔 보기: threshold
  return segs.map(([a, b], i) => ({ start: a, end: b, speaker: `SPEAKER_${String(labels[i]).padStart(2, "0")}` }));
}

function speakerAt(diar: Seg[], t0: number, t1: number): string {
  // 단어 구간과 가장 많이 겹치는 화자, 겹치는 게 없으면 가장 가까운 구간의 화자
  if (diar.length === 0) return "?";
  const ov = diar.map((d) => Math.min(t1, d.end) - Math.max(t0, d.start));
  const top = Math.max(...ov);
  if (top > 0) return diar[ov.indexOf(top)].speaker;
  const mid = (t0 + t1) / 2;
  const gap = diar.map((d) => Math.min(Math.abs(mid - d.start), Math.abs(mid - d.end)));
  return diar[gap.indexOf(Math.min(...gap))].speaker;
}

function toLines(words: Word[], diar: Seg[]): Line[] {
  // R3: 단어에 화자를 붙이고, 같은 화자가 이어 말하면 한 줄로 합친다
  // 받아쓰기 단어가 없으면(키 없음) 화자 분리 구간만으로 줄을 만든다
  const items: Word[] = words.length ? words : diar.map((d) => ({ word: "(받아쓰기 생략)", start: d.start, end: d.end }));
  const lines: Line[] = [];
  for (const w of items) {
    const spk = (w.speaker = speakerAt(diar, w.start, w.end));
    const last = lines[lines.length - 1];
    if (last && last.speaker === spk) {
      if (words.length) last.text += " " + w.word;
      last.end = w.end;
    } else lines.push({ speaker: spk, start: w.start, end: w.end, text: w.word });
  }
  return lines;
}

function nameSpeakers(y: Float32Array, diar: Seg[], enroll: Record<string, Float32Array> | null = null): Record<string, string> {
  // 화자 번호 → 이름: 등록 음성과 특징이 가장 닮은 사람끼리 1:1로 짝짓기 (사람 수가 적어 모든 짝을 다 따져 봄)
  const labs = [...new Set(diar.map((d) => d.speaker))].sort();
  const same: Record<string, string> = Object.fromEntries(labs.map((l) => [l, l]));
  if (!enroll || labs.length === 0) return same;
  const names = Object.keys(enroll);
  const clips = labs.map((l) => {
    const parts = diar.filter((d) => d.speaker === l).map((d) => y.subarray(Math.floor(d.start * SR), Math.floor(d.end * SR)));
    const out = new Float32Array(Math.min(SR * 20, parts.reduce((n, p) => n + p.length, 0)));
    let at = 0;
    for (const p of parts) {
      if (at >= out.length) break;
      out.set(p.subarray(0, out.length - at), at);
      at += Math.min(p.length, out.length - at);
    }
    return out;
  });
  const E = zscore([...clips.map(embed), ...names.map((n) => embed(enroll[n]))]);
  const sim = labs.map((_, i) => names.map((_, j) => cosine(E[i], E[labs.length + j])));
  let best: number[] = [];
  let bestScore = -Infinity;
  const pick = (i: number, used: number[], score: number): void => { // i번째 화자 번호에 이름 하나씩 (-1 = 이름 없음)
    if (i === labs.length) {
      if (score > bestScore) [best, bestScore] = [used.slice(), score];
      return;
    }
    for (let j = -1; j < names.length; j++) {
      if (j >= 0 && used.includes(j)) continue;
      if (j < 0 && labs.length <= names.length) continue; // 이름이 충분하면 모두 짝짓기
      pick(i + 1, [...used, j], score + (j >= 0 ? sim[i][j] : 0));
    }
  };
  pick(0, [], 0);
  return Object.fromEntries(labs.map((l, i) => [l, best[i] >= 0 ? names[best[i]] : l]));
}
function fmtTime(t: number): string {
  // 초 → '분:초' (예: 205 → 03:25)
  return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(Math.floor(t % 60)).padStart(2, "0")}`;
}
const made = makeMeeting();
const wav = userWav(() => {
  writeWav("meeting.wav", made.meeting, SR);
  return "meeting.wav";
});
const meeting = readWav(wav).y;
const enroll = wav === "meeting.wav" ? made.enroll : null; // 등록 음성은 합성 회의일 때만 있음
console.log(`회의 녹음 ${(meeting.length / SR).toFixed(1)}초 → ${wav}`);

const t0 = performance.now();
const heard = await transcribe(wav); // R1
const diar = diarize(meeting, 3); // R2 (화자 수를 알면 알려 주기, 모르면 null)
const lines = toLines(heard.words, diar); // R3
console.log(`처리 ${((performance.now() - t0) / 1000).toFixed(1)}초 | 받아쓰기 ${heard.engine} | 단어 ${heard.words.length}개 | 화자 분리 구간 ${diar.length}개 | 줄 ${lines.length}개\n`);
for (const ln of lines) console.log(`[${fmtTime(ln.start)}] ${ln.speaker}: ${ln.text}`);
check(fmtTime(205) === "03:25" && fmtTime(59.9) === "00:59", "1분 = 60초. 초 자리는 t % 60 입니다.");

const NAME = nameSpeakers(meeting, diar, enroll);
console.log("\n이름 붙이기:", NAME);
for (const ln of lines) ln.name = NAME[ln.speaker] ?? ln.speaker;
