// D10 · Part 5 · 평가표 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d10_eval.ts   (입력은 코드 안의 예시 결과)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}
function editCount<T>(r: T[], h: T[]): number {
  // 편집 거리(최소 고침 횟수): 한 줄씩만 들고 계산
  let prev = Array.from({ length: h.length + 1 }, (_, j) => j);
  for (let i = 1; i <= r.length; i++) {
    const cur = [i];
    for (let j = 1; j <= h.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (r[i - 1] === h[j - 1] ? 0 : 1)));
    prev = cur;
  }
  return prev[h.length];
}

function cer(ref: string | string[], hyp: string | string[]): number {
  // 글자 오류율 (jiwer.cer와 같은 방식: 앞뒤 공백 정리, 공백도 한 글자, 여러 문장은 합쳐서 계산)
  const R = Array.isArray(ref) ? ref : [ref];
  const H = Array.isArray(hyp) ? hyp : [hyp];
  let edits = 0;
  let total = 0;
  R.forEach((r, i) => {
    const rc = [...r.trim()];
    edits += editCount(rc, [...(H[i] ?? "").trim()]);
    total += rc.length;
  });
  if (total === 0) throw new Error("정답(ref)이 비어 있으면 오류율을 계산할 수 없어요");
  return edits / total;
}
const DIG = "영일이삼사오육칠팔구";
const UNITS = ["", "십", "백", "천"];

function num2kor(n: number): string {
  // 0~9999를 한글 읽기로: 2026 → 이천이십육 (만 이상은 그대로 둔다)
  if (n === 0) return "영";
  if (n >= 10000) return String(n);
  let s = "";
  [...String(n)].reverse().forEach((ch, i) => { // i = 0(일의 자리), 1(십), 2(백), 3(천)
    const d = Number(ch);
    if (d === 0) return;
    s = (d === 1 && i > 0 ? "" : DIG[d]) + UNITS[i] + s; // '일십' 대신 '십'
  });
  return s;
}

const HOURS = ["", "한", "두", "세", "네", "다섯", "여섯", "일곱", "여덟", "아홉", "열", "열한", "열두"]; // 시각은 고유어로 읽음

function readHour(n: number): string {
  // 시각: 3시 → 세 시, 12시 → 열두 시 (1~12는 고유어, 그 밖은 한자어)
  return (n >= 1 && n <= 12 ? HOURS[n] : num2kor(n)) + " 시";
}

function readMonth(n: number): string {
  // 달: 6월 → 유월, 10월 → 시월 (받침이 떨어지는 예외), 나머지는 한자어 + 월
  return n === 6 ? "유월" : n === 10 ? "시월" : num2kor(n) + "월";
}
const TERMS: Record<string, string> = { whisper: "위스퍼", api: "에이피아이", cer: "씨이알", pyannote: "파이아노트" }; // 바꿔 보기: 우리 회사 용어

function normalize(s: string): string {
  // 채점 전 정규화: 소문자 → 문장 부호 → 숫자를 한글로 → 용어 사전 → 공백 정리
  s = s.toLowerCase(); // ① 소문자
  s = s.replace(/(?<=\d),(?=\d)/g, ""); //    2,500 → 2500 (숫자 속 쉼표)
  s = s.replace(/[^\p{L}\p{N}_\s]/gu, " "); // ① 문장 부호 → 공백
  s = s.replace(/(\d+)\s*시/g, (_, n: string) => readHour(Number(n))); // ② 시각: 3시 → 세 시
  s = s.replace(/(\d+)\s*월/g, (_, n: string) => readMonth(Number(n))); // ② 달: 10월 → 시월
  s = s.replace(/\d+/g, (m) => num2kor(Number(m))); // ② 나머지 숫자 → 한글
  for (const [k, v] of Object.entries(TERMS)) s = s.replaceAll(k, v); // ③ 용어 사전
  return s.replace(/\s+/g, " ").trim(); // ④ 공백 정리
}
type Turn = { speaker: string; text: string; start: number; end: number };
type ActionItem = { owner: string; task: string; due: string };
type Summary = { summary: string[]; decisions: string[]; action_items: ActionItem[] };

type Word = { word: string; start: number; end: number; speaker?: string };

const KEY_POINTS: Record<string, string[]> = { // 핵심 사항: 이 중 하나라도 나오면 '담음'
  "받아쓰기 모델 = 위스퍼 스몰": ["위스퍼", "whisper"],
  "화자 분리 = 파이아노트": ["파이아노트", "pyannote"],
  "평가 = 정규화 후 글자 오류율": ["오류율", "cer"],
  "박대리 · 수요일 · 단어 시각 정렬": ["수요일"],
  "이연구원 · 목요일 · 평가 스크립트": ["목요일"],
};

function turnOf(turns: Turn[], t: number): number {
  // 시각 t가 속한(없으면 가장 가까운) 정답 발화 번호
  const d = turns.map((x) => (x.start <= t && t <= x.end ? 0 : Math.min(Math.abs(t - x.start), Math.abs(t - x.end))));
  return d.indexOf(Math.min(...d));
}

function evaluate(summary: Summary, how: string, words: Word[], name: Record<string, string>, turns: Turn[], refText: string): number {
  // 평가표: 받아쓰기 CER(정규화 전·후) · 단어별 화자 정확도 · 요약 핵심 사항 점검 → 요약 점수(0~1)
  const summaryText = normalize(JSON.stringify(summary));
  const found = Object.entries(KEY_POINTS).map(([k, kws]): [string, boolean] => [k, kws.some((w) => summaryText.includes(normalize(w)))]);
  const hit = found.filter(([, v]) => v).length;

  const hypText = words.map((w) => w.word).join(" ");
  const hits = words.map((w) => (name[w.speaker ?? "?"] ?? "?") === turns[turnOf(turns, (w.start + w.end) / 2)].speaker);
  const spkAcc = hits.length ? hits.filter(Boolean).length / hits.length : 0; // 단어가 없으면 0 (0 나누기 방지)

  console.log("평가표");
  console.log(`  받아쓰기 CER   정규화 전 ${(cer(refText, hypText) * 100).toFixed(1)}% → 정규화 후 ${(cer(normalize(refText), normalize(hypText)) * 100).toFixed(1)}%`);
  console.log(`  단어별 화자 정확도 ${(spkAcc * 100).toFixed(1)}% (단어 ${words.length}개)`);
  console.log(`  요약 점검 ${hit}/${found.length} (${how})`);
  for (const [k, v] of found) console.log(`    [${v ? "O" : " "}] ${k}`);
  return hit / Object.keys(KEY_POINTS).length;
}
