function makeMeeting(): { meeting: Float32Array; turns: Turn[]; enroll: Record<string, Float32Array> } {
  // → 회의 녹음, 정답 발화 구간(turns), 화자 등록 음성(enroll)
  const rnd = mulberry32(0);
  const pieces: Float32Array[] = [new Float32Array(Math.floor(0.5 * SR))];
  const turns: Turn[] = [];
  let t = 0.5;
  SCRIPT.forEach(([name, text], i) => {
    const y = synthVoice(Math.max(1, text.length * 0.12), VOICES[name], i + 1);
    turns.push({ speaker: name, text, start: t, end: t + y.length / SR });
    const gap = 0.5 + 0.4 * rnd(); // 발화 사이 쉼 0.5~0.9초
    pieces.push(y, new Float32Array(Math.floor(gap * SR)));
    t += y.length / SR + gap;
  });
  const meeting = new Float32Array(pieces.reduce((n, p) => n + p.length, 0));
  let at = 0;
  for (const p of pieces) {
    meeting.set(p, at);
    at += p.length;
  }
  const enroll: Record<string, Float32Array> = {};
  Object.entries(VOICES).forEach(([name, f0], i) => (enroll[name] = synthVoice(3, f0, 100 + i)));
  return { meeting, turns, enroll };
}
// R2 · R3: 화자 분리 · 줄 만들기 (수업 노트북의 pyannote·SpeechBrain 대신 로그 멜 특징 + 평균 연결 군집)
function embed(y: Float32Array): number[] {
  // 화자 특징(간단 버전): 로그 멜 80칸의 시간 평균에서 자기 평균을 뺀 '소리 모양'
  const S = logMel(y, SR);
  const mean = new Array<number>(N_MELS).fill(0);
  for (const f of S) f.forEach((v, k) => (mean[k] += v / Math.max(1, S.length)));
  const mu = mean.reduce((a, b) => a + b, 0) / N_MELS;
  return mean.map((v) => v - mu);
}

function zscore(E: number[][]): number[][] {
  // 특징마다 평균 0 · 표준편차 1 (표준편차가 0이면 나누지 않음)
  const dim = E[0].length;
  const mu = Array.from({ length: dim }, (_, k) => E.reduce((a, e) => a + e[k], 0) / E.length);
  const sd = Array.from({ length: dim }, (_, k) => Math.sqrt(E.reduce((a, e) => a + (e[k] - mu[k]) ** 2, 0) / E.length));
  return E.map((e) => e.map((v, k) => (v - mu[k]) / (sd[k] > 1e-9 ? sd[k] : 1)));
}

function cosine(a: number[], b: number[]): number {
  let ab = 0;
  let aa = 0;
  let bb = 0;
  a.forEach((v, k) => {
    ab += v * b[k];
    aa += v * v;
    bb += b[k] * b[k];
  });
  return ab / Math.max(Math.sqrt(aa * bb), 1e-9);
}

function cluster(E: number[][], k: number | null, threshold: number = 0.6): number[] {
  // 평균 연결 군집: 가장 가까운(코사인 거리) 두 무리를 합치기를 k개가 될 때까지(또는 거리가 threshold를 넘을 때까지)
  let groups = E.map((_, i) => [i]);
  const link = (A: number[], B: number[]): number => A.reduce((s, a) => s + B.reduce((t, b) => t + 1 - cosine(E[a], E[b]), 0), 0) / (A.length * B.length);
  while (groups.length > 1 && (k === null || groups.length > k)) {
    let best: [number, number, number] = [0, 1, Infinity];
    for (let i = 0; i < groups.length; i++) for (let j = i + 1; j < groups.length; j++) {
      const d = link(groups[i], groups[j]);
      if (d < best[2]) best = [i, j, d];
    }
    if (k === null && best[2] > threshold) break;
    groups[best[0]] = groups[best[0]].concat(groups[best[1]]);
    groups = groups.filter((_, i) => i !== best[1]);
  }
  const labels = new Array<number>(E.length).fill(0);
  groups.sort((A, B) => Math.min(...A) - Math.min(...B)).forEach((g, c) => g.forEach((i) => (labels[i] = c)));
  return labels;
}

function diarize(y: Float32Array, numSpeakers: number | null = null): Seg[] {
  // R2: 소리 구간 나누기 → 구간마다 특징 → 군집으로 화자 번호 붙이기
  const segs = speechSegments(y);
  if (segs.length < 2) return segs.map(([a, b]) => ({ start: a, end: b, speaker: "SPEAKER_00" }));
  const E = zscore(segs.map(([a, b]) => embed(y.subarray(Math.floor(a * SR), Math.floor(b * SR)))));
  const labels = cluster(E, numSpeakers ? Math.min(numSpeakers, segs.length) : null); // 바꿔 보기: threshold
  return segs.map(([a, b], i) => ({ start: a, end: b, speaker: `SPEAKER_${String(labels[i]).padStart(2, "0")}` }));
}

function speakerAt(diar: Seg[], t0: number, t1: number): string {
  // 단어 구간과 가장 많이 겹치는 화자, 겹치는 게 없으면 가장 가까운 구간의 화자
  if (diar.length === 0) return "?";
  const ov = diar.map((d) => Math.min(t1, d.end) - Math.max(t0, d.start));
  const top = Math.max(...ov);
  if (top > 0) return diar[ov.indexOf(top)].speaker;
  const mid = (t0 + t1) / 2;
  const gap = diar.map((d) => Math.min(Math.abs(mid - d.start), Math.abs(mid - d.end)));
  return diar[gap.indexOf(Math.min(...gap))].speaker;
}

function toLines(words: Word[], diar: Seg[]): Line[] {
  // R3: 단어에 화자를 붙이고, 같은 화자가 이어 말하면 한 줄로 합친다
  // 받아쓰기 단어가 없으면(키 없음) 화자 분리 구간만으로 줄을 만든다
  const items: Word[] = words.length ? words : diar.map((d) => ({ word: "(받아쓰기 생략)", start: d.start, end: d.end }));
  const lines: Line[] = [];
  for (const w of items) {
    const spk = (w.speaker = speakerAt(diar, w.start, w.end));
    const last = lines[lines.length - 1];
    if (last && last.speaker === spk) {
      if (words.length) last.text += " " + w.word;
      last.end = w.end;
    } else lines.push({ speaker: spk, start: w.start, end: w.end, text: w.word });
  }
  return lines;
}

function nameSpeakers(y: Float32Array, diar: Seg[], enroll: Record<string, Float32Array> | null = null): Record<string, string> {
  // 화자 번호 → 이름: 등록 음성과 특징이 가장 닮은 사람끼리 1:1로 짝짓기 (사람 수가 적어 모든 짝을 다 따져 봄)
  const labs = [...new Set(diar.map((d) => d.speaker))].sort();
  const same: Record<string, string> = Object.fromEntries(labs.map((l) => [l, l]));
  if (!enroll || labs.length === 0) return same;
  const names = Object.keys(enroll);
  const clips = labs.map((l) => {
    const parts = diar.filter((d) => d.speaker === l).map((d) => y.subarray(Math.floor(d.start * SR), Math.floor(d.end * SR)));
    const out = new Float32Array(Math.min(SR * 20, parts.reduce((n, p) => n + p.length, 0)));
    let at = 0;
    for (const p of parts) {
      if (at >= out.length) break;
      out.set(p.subarray(0, out.length - at), at);
      at += Math.min(p.length, out.length - at);
    }
    return out;
  });
  const E = zscore([...clips.map(embed), ...names.map((n) => embed(enroll[n]))]);
  const sim = labs.map((_, i) => names.map((_, j) => cosine(E[i], E[labs.length + j])));
  let best: number[] = [];
  let bestScore = -Infinity;
  const pick = (i: number, used: number[], score: number): void => { // i번째 화자 번호에 이름 하나씩 (-1 = 이름 없음)
    if (i === labs.length) {
      if (score > bestScore) [best, bestScore] = [used.slice(), score];
      return;
    }
    for (let j = -1; j < names.length; j++) {
      if (j >= 0 && used.includes(j)) continue;
      if (j < 0 && labs.length <= names.length) continue; // 이름이 충분하면 모두 짝짓기
      pick(i + 1, [...used, j], score + (j >= 0 ? sim[i][j] : 0));
    }
  };
  pick(0, [], 0);
  return Object.fromEntries(labs.map((l, i) => [l, best[i] >= 0 ? names[best[i]] : l]));
}
function fmtTime(t: number): string {
  // 초 → '분:초' (예: 205 → 03:25)
  return `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(Math.floor(t % 60)).padStart(2, "0")}`;
}
const SYSTEM = "당신은 한국어 회의록을 정리하는 비서입니다. 녹취에 없는 내용은 절대 지어내지 않습니다.";
const MODEL = "claude-haiku-5-5"; // 바꿔 보기: 더 꼼꼼한 요약은 "claude-sonnet-5-5"

function buildPrompt(transcript: string): string {
  return `아래는 음성 인식으로 만든 회의 녹취입니다. 받아쓰기 오류가 있을 수 있으니 문맥으로 이해하세요.

<녹취>
${transcript}
</녹취>

다음 JSON 형식으로만 답하세요. 다른 말은 쓰지 마세요.
{"summary": ["요약 문장 (3개 이내)"],
 "decisions": ["결정된 사항"],
 "action_items": [{"owner": "담당자 이름", "task": "할 일", "due": "기한 (말하지 않았으면 빈 문자열)"}]}

규칙: 녹취에 없는 내용은 쓰지 않습니다. 담당자와 기한은 녹취에서 말한 그대로 씁니다.`;
}

const DAYS = ["월요일", "화요일", "수요일", "목요일", "금요일", "다음 주", "오늘", "내일"];

function ruleBasedSummary(lines: Line[]): Summary {
  // 키 없이 쓰는 규칙 기반 요약: 결정 낱말 · 요일이 든 문장을 골라낸다
  const decisions: string[] = [];
  const actions: ActionItem[] = [];
  for (const ln of lines) {
    for (const t of ln.text.split(/(?<=[.?!])\s+/)) { // 한 줄을 문장으로 나눠서 봄
      if (["결정", "정했", "쓰기로", "하기로"].some((k) => t.includes(k))) decisions.push(t);
      const due = DAYS.find((d) => t.includes(d)) ?? "";
      if (due && ["겠습니다", "합시다", "까지"].some((k) => t.includes(k))) actions.push({ owner: ln.name ?? ln.speaker, task: t, due });
    }
  }
  const people = new Set(lines.map((l) => l.name ?? l.speaker));
  return {
    summary: [`발언 ${lines.length}건, 참석자 ${people.size}명`, `결정 사항 ${decisions.length}건, 할 일 ${actions.length}건`],
    decisions,
    action_items: actions,
  };
}

function parseJson(text: string): Summary {
  // LLM 답에서 JSON 꺼내기: ```json ... ``` 떼어 내고, 키가 없거나 모양이 다르면 빈 목록
  text = text.trim();
  if (text.startsWith("```")) text = text.slice(text.indexOf("\n") + 1, text.lastIndexOf("```"));
  const data: unknown = JSON.parse(text);
  const obj = isRecord(data) ? data : {};
  const strs = (v: unknown): string[] => (Array.isArray(v) ? v.map(String) : []);
  const items: unknown[] = Array.isArray(obj.action_items) ? obj.action_items : [];
  return {
    summary: strs(obj.summary),
    decisions: strs(obj.decisions),
    action_items: items.map((a) => // 할 일이 문자열이면 task로
      isRecord(a) ? { owner: String(a.owner ?? ""), task: String(a.task ?? ""), due: String(a.due ?? "") } : { owner: "", task: String(a), due: "" }),
  };
}

async function summarize(lines: Line[], transcript: string): Promise<[Summary, string]> {
  // R4: ANTHROPIC_API_KEY가 있으면 Claude, 없거나 실패하면 규칙 기반 → [요약, 방법]
  if (process.env.ANTHROPIC_API_KEY) {
    try {
      return [parseJson(await callClaude(SYSTEM, buildPrompt(transcript), MODEL, 1500)), "Claude"];
    } catch (e) {
      console.log(`[주의] LLM 요약 실패 → 규칙 기반으로 대신: ${String(e).slice(0, 120)}`);
    }
  }
  return [ruleBasedSummary(lines), "규칙 기반"];
}

function renderMinutes(summary: Summary, lines: Line[], title: string = "회의록 (자동 생성)"): string {
  const md = [`# ${title}`, "", "## 요약", ...summary.summary.map((s) => `- ${s}`)];
  md.push("", "## 결정 사항", ...(summary.decisions.length ? summary.decisions.map((d) => `- ${d}`) : ["- (없음)"]));
  md.push("", "## 할 일", "| 담당 | 할 일 | 기한 |", "|---|---|---|");
  md.push(...(summary.action_items.length ? summary.action_items.map((a) => `| ${a.owner} | ${a.task} | ${a.due} |`) : ["| - | - | - |"]));
  md.push("", "## 녹취", ...(lines.length ? lines.map((l) => `- **[${fmtTime(l.start)}] ${l.name ?? l.speaker}**: ${l.text}`) : ["- (인식된 말 없음)"]));
  return md.join("\n");
}
type Minutes = { md: string; summary: Summary; words: Word[]; name: Record<string, string>; how: string; engine: string };

async function makeMinutes(wavPath: string, numSpeakers: number | null = null, enroll: Record<string, Float32Array> | null = null): Promise<Minutes> {
  // 녹음 파일 하나 → 회의록 마크다운 (R1 받아쓰기 → R2 화자 분리 → R3 줄 → 이름 → R4 요약)
  const { y } = readWav(wavPath);
  const heard = await transcribe(wavPath); // R1 (OPENAI_API_KEY 없으면 단어 없이 진행)
  const diar = diarize(y, numSpeakers); // R2
  const lines = toLines(heard.words, diar); // R3
  const name = nameSpeakers(y, diar, enroll);
  for (const ln of lines) ln.name = name[ln.speaker] ?? ln.speaker;
  const transcript = lines.map((l) => `[${fmtTime(l.start)}] ${l.name}: ${l.text}`).join("\n");
  const [summary, how] = await summarize(lines, transcript); // R4
  const md = renderMinutes(summary, lines, `회의록 (자동 생성 · 받아쓰기: ${heard.engine} · 요약: ${how})`);
  return { md, summary, words: heard.words, name, how, engine: heard.engine };
}
async function runDemo(audioPath: string | null, nSpk: number): Promise<string> {
  // 데모 화면에서 부르는 함수: 녹음 파일 경로 → 회의록 마크다운
  if (!audioPath) return "녹음 파일을 올려 주세요.";
  return (await makeMinutes(audioPath, nSpk > 0 ? nSpk : null)).md;
}

const PAGE = `<!doctype html><meta charset="utf-8"><title>자동 회의록 생성기</title>
<h1>자동 회의록 생성기 (D10 미니 프로젝트)</h1>
<p>받아쓰기 → 화자 분리 → 요약 · 결정 사항 · 할 일 (16비트 WAV)</p>
<input type="file" id="f" accept=".wav"> 화자 수 (모르면 0) <input type="number" id="n" value="0" min="0">
<button id="go">회의록 만들기</button><pre id="out"></pre>
<script>
document.getElementById("go").onclick = async () => {
  const file = document.getElementById("f").files[0];
  const out = document.getElementById("out");
  if (!file) { out.textContent = "녹음 파일을 올려 주세요."; return; }
  out.textContent = "처리 중…";
  const res = await fetch("/minutes?n=" + document.getElementById("n").value, { method: "POST", body: file });
  out.textContent = await res.text();
};
</script>`;

const MAX_BYTES = 50 * 1024 * 1024; // 올리는 파일 상한 50MB
const LOCAL = new Set(["localhost", "127.0.0.1", "[::1]"]);

function isLocal(req: IncomingMessage): boolean {
  // 이 컴퓨터에서 연 화면의 요청만 받는다: Host(와 있으면 Origin)가 localhost · 127.0.0.1 이어야 함
  const host = (req.headers.host ?? "").replace(/:\d+$/, "");
  const origin = req.headers.origin;
  if (!LOCAL.has(host)) return false;
  if (!origin) return true;
  try {
    return LOCAL.has(new URL(origin).hostname);
  } catch {
    return false;
  }
}

function handle(req: IncomingMessage, res: ServerResponse): void {
  const text = (code: number, body: string): void => void res.writeHead(code, { "content-type": "text/plain; charset=utf-8" }).end(body);
  if (!isLocal(req)) return text(403, "이 컴퓨터(localhost)에서만 쓸 수 있어요.");
  if (req.method === "POST" && req.url?.startsWith("/minutes")) {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on("data", (c: Buffer) => {
      size += c.length;
      if (size > MAX_BYTES) {
        tooBig = true;
        text(413, "파일이 50MB보다 커요.");
        req.destroy();
      } else chunks.push(c);
    });
    req.on("end", () => {
      if (tooBig) return;
      const n = Number(new URL(req.url ?? "/", "http://localhost").searchParams.get("n") ?? 0);
      const path = `upload_${randomUUID()}.wav`; // 요청마다 다른 임시 파일
      writeFileSync(path, Buffer.concat(chunks));
      runDemo(path, n)
        .then((md) => text(200, md))
        .catch((e: unknown) => text(400, `처리 실패: ${String(e).slice(0, 120)}`))
        .finally(() => rmSync(path, { force: true }));
    });
    return;
  }
  res.writeHead(200, { "content-type": "text/html; charset=utf-8" }).end(PAGE);
}

if (process.argv.includes("--serve")) {
  createServer(handle).listen(7860, "127.0.0.1", () => console.log("데모 화면: http://127.0.0.1:7860"));
} else {
  const { meeting, enroll } = makeMeeting();
  const wav = userWav(() => {
    writeWav("meeting.wav", meeting, SR);
    return "meeting.wav";
  });
  const t0 = performance.now();
  const md = await runDemo(wav, wav === "meeting.wav" ? 3 : 0); // 화면에서 파일을 올린 것과 같은 경로로 실행
  console.log(`전체 ${((performance.now() - t0) / 1000).toFixed(1)}초\n`);
  console.log(md.slice(0, 1500));
  writeFileSync("meeting_minutes.md", md);
  if (wav === "meeting.wav") {
    const full = await makeMinutes(wav, 3, enroll); // 합성 회의는 등록 음성으로 이름까지
    console.log("\n이름 붙이기:", full.name, "| 요약 방법:", full.how);
  }
  console.log("저장: meeting_minutes.md (화면은 --serve)");
}
